ALTER FUNCTION public.staff_workspace(uuid,uuid) RENAME TO staff_workspace_base;
CREATE FUNCTION public.staff_workspace(_actor uuid,_person uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE demo boolean; r jsonb; ids uuid[]; extra jsonb; BEGIN demo:=public.staff_access(_actor); PERFORM public.refresh_staff_attention(_actor); r:=public.staff_workspace_base(_actor,_person); SELECT array_agg(id) INTO ids FROM public.persons WHERE NOT demo OR id IN('809f85d8-4640-4860-badc-45cba7b5fb4a','ed5895e3-934e-4220-91a1-f70cc937103c');
SELECT COALESCE(jsonb_agg(jsonb_build_object('source','attention','source_id',a.id,'person_id',a.person_id,'kind','overdue','description',a.kind,'sacred',false,'created_at',a.due_at,'status',a.status,'assigned_to',a.assigned_to,'closing_note',a.note)),'[]'::jsonb) INTO extra FROM public.staff_attention a WHERE a.person_id=ANY(ids) AND a.overdue AND a.status<>'closed' AND (NOT demo OR a.hosting_id IS NULL OR a.hosting_id IN(SELECT id FROM public.hostings WHERE guest_id=ANY(ids) AND host_id=ANY(ids)));
RETURN r||jsonb_build_object('alerts',(r->'alerts')||extra,'attention_count',(SELECT count(*) FROM public.staff_attention a WHERE a.person_id=ANY(ids) AND a.status<>'closed' AND (NOT demo OR a.hosting_id IS NULL OR a.hosting_id IN(SELECT id FROM public.hostings WHERE guest_id=ANY(ids) AND host_id=ANY(ids))))); END $$;
REVOKE ALL ON FUNCTION public.staff_workspace(uuid,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.staff_workspace(uuid,uuid) TO service_role;